1878659','football-premier-league-2026-27-401878659','epl-2026-27-129297','event:football:premier-league:401879062','football-premier-league-2026-27-401879062','epl-2026-27-129298','event:football:premier-league:401879061','football-premier-league-2026-27-401879061','epl-2026-27-129299','event:football:premier-league:401879060','football-premier-league-2026-27-401879060','epl-2026-27-129300','event:football:premier-league:401879059','football-premier-league-2026-27-401879059','epl-2026-27-129301','event:football:premier-league:401879058','football-premier-league-2026-27-401879058','epl-2026-27-129302','event:football:premier-league:401878658','football-premier-league-2026-27-401878658']::text[];
 historical_ids constant text[]:=array['event:premier-league:128968','epl-2026-27-128968','event:football:premier-league:401879273','football-premier-league-2026-27-401879273','event:premier-league:128969','epl-2026-27-128969','event:football:premier-league:401879272','football-premier-league-2026-27-401879272']::text[];
 canonical_hist constant text[]:=array['event:premier-league:128968','event:premier-league:128969']::text[];
 event_tables constant text[]:=array['nothingsports_consensus_receipts','nothingsports_consensus_votes','nothingsports_fixture_participation','nothingsports_friend_activity','nothingsports_inbox','nothingsports_live_rating_alerts','nothingsports_marquee_campaigns','nothingsports_nsc_completed_fixtures','nothingsports_nsc_contributions','nothingsports_nsc_foresight_settlements','nothingsports_nsc_likes','nothingsports_nsc_marquee_sessions','nothingsports_nsc_points','nothingsports_nsc_prediction_revisions','nothingsports_nsc_presence','nothingsports_nsc_rating_history','nothingsports_prediction_rules','nothingsports_predictions','nothingsports_reminders','nothingsports_saved_game_media','nothingsports_score_fixtures','nothingsports_score_votes','nothingsports_editorial_maintenance']::text[];
 allowed_legacy constant text[]:=array['nothingsports_nsc_contributions','nothingsports_nsc_points','nothingsports_nsc_rating_history','nothingsports_predictions','nothingsports_prediction_rules','nothingsports_score_votes','nothingsports_score_fixtures']::text[];
 expected_functions constant jsonb:='{"nothingsports_recovery.fixture_alias_v1(text)":"a75cba265ff5f09f51a967d6a97e7fb0","nothingsports_recovery.alias_guard_v1()":"74bd214300fa55b327a96073c1f804b2","public.nothingsports_nsc_award_points(uuid,text,text,integer,timestamp with time zone)":"da51784b2689f1ca1cb8d35d8ee7330d","public.nothingsports_nsc_submit_rating(uuid,text,text,integer,text[],timestamp with time zone)":"9c518be85c035116402b132d175dbace","public.nothingsports_rate_v2(uuid,text,text,integer,timestamp with time zone,timestamp with time zone,text,text,text)":"417b81e1921abec2ff809314865dbd9f","public.nothingsports_resolve_predictions(text,timestamp with time zone,text)":"078b9a1a40c5ad78f99e9f5245a64854","public.nothingsports_resolve_predictions_legacy(text,timestamp with time zone,text)":"93cfa3d90a028607a0653e5ef4b8a82a"}'::jsonb;
 t text;sig text;expected text;state_hash text;identity_hash text;n bigint;
 before_state jsonb:='{}';post_state jsonb:='{}';security_before jsonb;security_after jsonb;
 trigger_state jsonb;function_post jsonb;security_post jsonb;aux_before jsonb;aux_after jsonb;added_parents jsonb:='[]';added_rules jsonb:='[]';
 world jsonb;source_key text;canonical text;confirmed_finish timestamptz;legacy_rule public.nothingsports_prediction_rules;inv jsonb;
begin
 perform pg_advisory_xact_lock(hashtext('sportscal:coverage-repair:v1'));
 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 select inventory into inv from nothingsports_recovery.coverage_repair_versions where version=version_id and completed_at is not null;
 if inv is not null then
  for sig,expected in select * from jsonb_each_text(inv->'functionPostState') loop
   if to_regprocedure(sig) is null or md5(pg_get_functiondef(sig::regprocedure)) is distinct from expected then raise exception 'EPL completed bridge function drift: %',sig;end if;
  end loop;
  return;
 end if;
 if to_regprocedure('nothingsports_recovery.epl_reward_clock_v1(text,text,timestamp with time zone)') is not null or to_regprocedure('nothingsports_recovery.epl_operating_ids_v1(text)') is not null or to_regprocedure('nothingsports_recovery.epl_identity_ready_v1()') is not null or to_regprocedure('public.nothingsports_epl_identity_ready()') is not null then raise exception 'EPL helper names already exist without a completed reviewed bridge';end if;
 for sig,expected in select * from jsonb_each_text(expected_functions) loop
  if to_regprocedure(sig) is null or md5(pg_get_functiondef(sig::regprocedure)) is distinct from expected then raise exception 'EPL baseline function drift: %',sig;end if;
  if has_function_privilege('anon',sig,'execute') or has_function_privilege('authenticated',sig,'execute') then raise exception 'EPL writer/helper client grant requires review: %',sig;end if;
  if sig<>'nothingsports_recovery.alias_guard_v1()' and not has_function_privilege('service_role',sig,'execute') then raise exception 'EPL existing service grant missing: %',sig;end if;
 end loop;
 if exists(select 1 from information_schema.columns c join information_schema.tables b using(table_schema,table_name) where c.table_schema='public' and c.column_name='event_id' and b.table_type='BASE TABLE' and not c.table_name=any(event_tables)) then raise exception 'EPL new event activity table requires review';end if;
 foreach t in array event_tables loop execute format('lock table public.%I in share row exclusive mode',t);end loop;
 lock table public.nothingsports_fixture_current in share mode;
 lock table public.nothingsports_reminder_intents,public.nothingsports_chat_rooms,public.nothingsports_user_state in share row exclusive mode;
 -- Canonical identity agreement, without treating a recent collection check as
 -- a new fact. The existing accepted source's observation fields are not written.
 select count(*),md5(string_agg(concat(fixture_id,':',fixture->>'competitionId',':',fixture->>'season',':',fixture->'participantIds'->>0,':',fixture->'participantIds'->>1),'|' order by fixture_id)) into n,identity_hash
 from public.nothingsports_fixture_current where source_id='live-premier-league';
 if n<>380 or identity_hash is distinct from 'ff2c82c193124a1c9d7b1d6338c66fef' then raise exception 'EPL accepted complete primary identity review has changed';end if;

 -- Existing activity is read forward only in the reviewed historical scopes.
 -- Refuse new aliases/rooms/intent/receipt surfaces instead of losing them.
 foreach t in array event_tables loop
  if t='nothingsports_editorial_maintenance' then
   -- Editorial owns raw primary fixture IDs, not the NSC action namespace.
   -- Preserve its entire private world draft and refuse retired calendar keys.
   execute format('select count(*) from public.%I where event_id=any($1) and event_id not like %L',t,'epl-2026-27-%') into n using mapped_ids;
   if n>0 then raise exception 'EPL retired editorial identity requires review';end if;
  else
   execute format('select count(*) from public.%I where event_id=any($1) and not event_id=any($2)',t) into n using mapped_ids,historical_ids;
   if n>0 then raise exception 'EPL newly discovered legacy activity requires review: %',t;end if;
   if not t=any(allowed_legacy) then
    execute format('select count(*) from public.%I where event_id=any($1)',t) into n using mapped_ids;
    if n>0 then raise exception 'EPL unsupported historical alias activity requires review: %',t;end if;
   end if;
  end if;
  execute format('select md5(coalesce(string_agg(to_jsonb(r)::text,'''' order by to_jsonb(r)::text),'''')) from public.%I r where event_id=any($1)',t) into state_hash using ids;
  before_state:=before_state||jsonb_build_object(t,state_hash);
 end loop;
 if exists(select 1 from public.nothingsports_reminder_intents where fixture_id=any(mapped_ids)) or exists(select 1 from public.nothingsports_chat_rooms where canonical_fixture_id=any(mapped_ids)) then raise exception 'EPL existing legacy reminder choice/private room requires review';end if;
 select jsonb_build_object(
 'reminderIntents',(select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by to_jsonb(r)::text),'')) from public.nothingsports_reminder_intents r where r.fixture_id=any(ids) or r.aliases ?| ids),
 'privateRooms',(select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by to_jsonb(r)::text),'')) from public.nothingsports_chat_rooms r where r.canonical_fixture_id=any(ids)),
 'savedState',(select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by to_jsonb(r)::text),'')) from public.nothingsports_user_state r)) into aux_before;
 select jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('acl',p.proacl::text,'owner',p.proowner,'definer',p.prosecdef,'config',p.proconfig)) from pg_proc p where p.oid in(select key::regprocedure::oid from jsonb_each(expected_functions)) into security_before;
 select jsonb_agg(jsonb_build_object('table',c.relname,'name',g.tgname,'state',g.tgenabled,'definition',pg_get_triggerdef(g.oid)) order by c.relname,g.tgname) from pg_trigger g join pg_class c on c.oid=g.tgrelid join pg_namespace ns on ns.oid=c.relnamespace where ns.nspname='public' and c.relname=any(event_tables) and not g.tgisinternal into trigger_state;
 if exists(select 1 from pg_trigger g where g.tgrelid='public.nothingsports_score_fixtures'::regclass and g.tgname='prediction_rule' and g.tgenabled<>'O') or not exists(select 1 from pg_trigger g where g.tgrelid='public.nothingsports_score_fixtures'::regclass and g.tgname='prediction_rule') then raise exception 'EPL parent/rule trigger baseline requires review';end if;
 insert into nothingsports_recovery.coverage_repair_versions(version) values(version_id) on conflict do nothing;
 for sig,expected in select * from jsonb_each_text(expected_functions) loop
  insert into nothingsports_recovery.coverage_repair_rows values(version_id,'@function',sig,jsonb_build_object('definition',pg_get_functiondef(sig::regprocedure))) on conflict do nothing;
 end loop;
 -- These are noncustomer world records, derived from the accepted primary.
 -- A scheduled end window never creates a confirmed-end or new rule cutoff.
 foreach canonical in array canonical_hist loop
  source_key:='epl-2026-27-'||split_part(canonical,':',3);
  select fixture into world from public.nothingsports_fixture_current where source_id='live-premier-league' and fixture_id=source_key;
  if world->>'canonicalEventId' is distinct from canonical or world->>'competitionId' is distinct from 'competition:premier-league-2026-27' or world->>'season' is distinct from '2026/27' or world->>'status' is distinct from 'completed' or world->>'timePrecision' is distinct from 'exact' or world->>'startTimeUtc' is null or coalesce(world->>'timeTbc','false')='true' or coalesce(world->>'startTimeTbc','false')='true' or coalesce(world->>'dateOnly','false')='true' then raise exception 'EPL historical primary world facts require review: %',canonical;end if;
  if exists(select 1 from public.nothingsports_score_fixtures r where r.event_id=canonical and (r.starts_at is distinct from (world->>'startTimeUtc')::timestamptz or r.status is distinct from (world->>'status'))) then raise exception 'EPL canonical world parent differs from accepted primary: %',canonical;end if;
  confirmed_finish:=(coalesce(world->>'actualEndTimeUtc',world->>'completedAt',world->>'resultPublishedAt'))::timestamptz;
  if confirmed_finish is not null and (confirmed_finish>clock_timestamp() or confirmed_finish<(world->>'startTimeUtc')::timestamptz) then raise exception 'EPL historical completion fact requires review: %',canonical;end if;
  if not exists(select 1 from public.nothingsports_score_fixtures where event_id=canonical) then
   alter table public.nothingsports_score_fixtures disable trigger prediction_rule;
   insert into public.nothingsports_score_fixtures(event_id,sport,gender,starts_at,ends_at,status)
   select canonical,'football',r.gender,(world->>'startTimeUtc')::timestamptz,confirmed_finish,world->>'status' from public.nothingsports_score_fixtures r where r.event_id=case canonical when 'event:premier-league:128968' then 'event:football:premier-league:401879273' else 'event:football:premier-league:401879272' end;
   if not found then raise exception 'EPL required original world parent is missing: %',canonical;end if;
   alter table public.nothingsports_score_fixtures enable trigger prediction_rule;
   added_parents:=added_parents||jsonb_build_array(canonical);
  end if;
  select * into legacy_rule from public.nothingsports_prediction_rules where event_id=case canonical when 'event:premier-league:128968' then 'event:football:premier-league:401879273' else 'event:football:premier-league:401879272' end;
  if not found then raise exception 'EPL original applicable rule is missing: %',canonical;end if;
  if exists(select 1 from public.nothingsports_prediction_rules r where r.event_id=canonical and (to_jsonb(r)-'event_id') is distinct from (to_jsonb(legacy_rule)-'event_id')) then raise exception 'EPL original/canonical rules differ: %',canonical;end if;
  if not exists(select 1 from public.nothingsports_prediction_rules where event_id=canonical) then
   insert into public.nothingsports_prediction_rules(event_id,version,completed_at,cutoff,settled_at) values(canonical,legacy_rule.version,legacy_rule.completed_at,legacy_rule.cutoff,legacy_rule.settled_at);
   added_rules:=added_rules||jsonb_build_array(canonical);
  end if;
 end loop;
