$function$;$ddl_fixture_alias_v1$;
 execute $ddl_alias_guard_v1$CREATE OR REPLACE FUNCTION nothingsports_recovery.alias_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare reviewed_clock jsonb;world_row public.nothingsports_score_fixtures;expected_phase text;incoming_phase text;begin
 -- A newly settled historic forecast retains its original FK and identity.
 -- All other tables and sporting namespaces keep the existing alias guard.
 if tg_table_name='nothingsports_consensus_receipts' then
  if new.event_id<>nothingsports_recovery.fixture_alias_v1(new.event_id)
   and cardinality(nothingsports_recovery.epl_operating_ids_v1(new.event_id))>1
   and exists(select 1 from public.nothingsports_predictions x where x.event_id=new.event_id and x.user_id=new.user_id)
  then return new;end if;
 end if;
 new.event_id := nothingsports_recovery.fixture_alias_v1(new.event_id);
 if new.event_id like 'event:premier-league:%' then
  if tg_table_name='nothingsports_score_fixtures' then
   reviewed_clock:=nothingsports_recovery.epl_reward_clock_v1(new.event_id,new.status,new.ends_at);
   if reviewed_clock is not null then new.starts_at:=(reviewed_clock->>'starts_at')::timestamptz;new.ends_at:=(reviewed_clock->>'ends_at')::timestamptz;new.status:=reviewed_clock->>'status';end if;
  elsif tg_op='INSERT' and tg_table_name in('nothingsports_predictions','nothingsports_nsc_contributions') then
   select * into world_row from public.nothingsports_score_fixtures where event_id=new.event_id;
   reviewed_clock:=nothingsports_recovery.epl_reward_clock_v1(new.event_id,world_row.status,world_row.ends_at);
   if reviewed_clock is not null then
    expected_phase:=case when reviewed_clock->>'status' in('cancelled','canceled','abandoned','postponed') then null when reviewed_clock->>'status' in('completed','finished','final') then 'impact' when reviewed_clock->>'status' in('live','inprogress','in_progress','in-progress') then 'pulse' when reviewed_clock->>'starts_at' is null or clock_timestamp()<(reviewed_clock->>'starts_at')::timestamptz then 'heat' when clock_timestamp()<(reviewed_clock->>'ends_at')::timestamptz then 'pulse' else 'impact' end;
    if tg_table_name='nothingsports_predictions' then incoming_phase:='heat';if reviewed_clock->>'starts_at' is null and new.result='pending' then raise exception 'phase_action_mismatch';end if;else incoming_phase:=new.phase;end if;
    if incoming_phase is distinct from expected_phase then raise exception 'phase_action_mismatch';end if;
   end if;
  end if;
 end if;
 if tg_table_name='nothingsports_nsc_points' and tg_op='INSERT' then if exists(select 1 from public.nothingsports_nsc_points p where p.user_id=new.user_id and nothingsports_recovery.fixture_alias_v1(p.event_id)=new.event_id and p.action_key=new.action_key) then return null; end if; end if; -- bledisloe-pending-timing-v1
 if tg_table_name='nothingsports_reminders' and new.event_id='rugby-australia-new-zealand-2026-10-17' then
 if new.dispatched_at is null and new.delivery_started_at is null and new.delivery_mode='match-15' then
 new.starts_at:='2026-10-17T05:00:00Z'::timestamptz;new.remind_at:='2026-10-17T04:45:00Z'::timestamptz;new.schedule_starts_at:=new.starts_at;
 end if;end if;
 return new; end $function$;$ddl_alias_guard_v1$;
 execute $ddl_nothingsports_nsc_award_points$CREATE OR REPLACE FUNCTION public.nothingsports_nsc_award_points(target_user_id uuid, target_event_id text, target_action_key text, requested_points integer, awarded_time timestamp with time zone DEFAULT now())
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare award integer;fixture_total integer;day_total integer;begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 if requested_points<1 or requested_points>25 or target_event_id='' then return 0;end if;
 if awarded_time<(select started_at from public.nothingsports_score_epoch limit 1) then return 0;end if;
 perform pg_advisory_xact_lock(hashtextextended(target_user_id::text,0));
 if target_action_key in('heat_rating','foresight_bonus') and not exists(select 1 from public.nothingsports_predictions where user_id=target_user_id and event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id))) then return 0;end if;
 award:=case target_action_key when 'heat_rating' then 1 when 'foresight_bonus' then 19 else requested_points end;
 if target_action_key not in('heat_rating','foresight_bonus','follow_person','followed_by_person') then
 select coalesce(sum(points),0) into fixture_total from public.nothingsports_nsc_points where user_id=target_user_id and event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and action_key not in('foresight_bonus','picks_copied','follow_person','followed_by_person');
 select coalesce(sum(points),0) into day_total from public.nothingsports_nsc_points where user_id=target_user_id and sydney_day=(awarded_time at time zone 'Australia/Sydney')::date and action_key not in('foresight_bonus','picks_copied','follow_person','followed_by_person');
 award:=greatest(0,least(award,10-fixture_total,25-day_total));if award=0 then return 0;end if;
 end if;
 insert into public.nothingsports_nsc_points(user_id,event_id,action_key,points,sydney_day,awarded_at,sport)
 values(target_user_id,target_event_id,target_action_key,award,(awarded_time at time zone 'Australia/Sydney')::date,awarded_time,(select sport from public.nothingsports_score_fixtures where event_id=target_event_id)) on conflict do nothing;
 if not found then return 0;end if;return award;
end $function$;$ddl_nothingsports_nsc_award_points$;
 execute $ddl_nothingsports_nsc_submit_rating$CREATE OR REPLACE FUNCTION public.nothingsports_nsc_submit_rating(target_user_id uuid, target_event_id text, target_phase text, target_rating integer, target_tags text[] DEFAULT '{}'::text[], submitted_time timestamp with time zone DEFAULT now())
 RETURNS TABLE(event_id text, phase text, rating smallint, tags text[], submitted_at timestamp with time zone, points_awarded integer, replayed boolean)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  existing public.nothingsports_nsc_contributions%rowtype;
  normalized_tags text[];
  rating_points integer:=0;
  tag_points integer:=0;
  effective_time timestamptz:=coalesce(submitted_time,now());
begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

  if target_user_id is null or coalesce(target_event_id,'')='' or target_phase is null or target_phase not in ('heat','impact') or target_rating is null or target_rating not between 1 and 5 then
    raise exception using errcode='22023',message='invalid_nsc_submission';
  end if;

  select coalesce(array_agg(item order by item),'{}'::text[])
  into normalized_tags
  from (
    select distinct item
    from unnest(coalesce(target_tags,'{}'::text[])) as expanded(item)
    where item is not null and item<>''
  ) distinct_tags;

  if cardinality(normalized_tags)>3
    or (target_rating<4 and cardinality(normalized_tags)>0)
    or (target_phase='heat' and not (normalized_tags <@ array['Box office','Big stakes','Rivalry','Star power','National interest','Great storyline']::text[]))
    or (target_phase='impact' and not (normalized_tags <@ array['Thrilling','Eye-popping','Mind-blowing','Emotional','Electric atmosphere','Pure chaos']::text[]))
  then
    raise exception using errcode='22023',message='invalid_nsc_submission';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(target_user_id::text,0));
  select contribution.* into existing
  from public.nothingsports_nsc_contributions contribution
  where contribution.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id))
    and contribution.user_id=target_user_id
    and contribution.phase=target_phase
    and contribution.bucket_start='1970-01-01T00:00:00Z'::timestamptz
  order by greatest(contribution.updated_at,contribution.submitted_at) desc nulls last,(contribution.event_id=target_event_id) desc,contribution.contribution_id
  limit 1 for update;

  if found then
    if existing.rating<>target_rating
      or not (coalesce(existing.tags,'{}'::text[]) <@ normalized_tags)
      or not (normalized_tags <@ coalesce(existing.tags,'{}'::text[]))
    then
      raise exception using errcode='P0001',message='nsc_already_submitted';
    end if;
    select coalesce(sum(point.points),0)::integer into points_awarded
    from public.nothingsports_nsc_points point
    where point.user_id=target_user_id
      and point.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id))
      and point.action_key in (target_phase||'_rating',target_phase||'_valid_tags');
    return query select existing.event_id,existing.phase,existing.rating,existing.tags,existing.submitted_at,points_awarded,true;
    return;
  end if;

  insert into public.nothingsports_nsc_contributions(
    event_id,user_id,phase,bucket_start,rating,tags,submitted_at,created_at,updated_at
  ) values(
    target_event_id,target_user_id,target_phase,'1970-01-01T00:00:00Z',target_rating,normalized_tags,effective_time,effective_time,effective_time
  ) returning * into existing;

  rating_points:=public.nothingsports_nsc_award_points(
    target_user_id,target_event_id,target_phase||'_rating',case when target_phase='heat' then 2 else 3 end,effective_time
  );
  if cardinality(normalized_tags)>0 then
    tag_points:=public.nothingsports_nsc_award_points(
      target_user_id,target_event_id,target_phase||'_valid_tags',1,effective_time
    );
  end if;
  points_awarded:=rating_points+tag_points;
  return query select existing.event_id,existing.phase,existing.rating,existing.tags,existing.submitted_at,points_awarded,false;
end;
$function$;$ddl_nothingsports_nsc_submit_rating$;
 execute $ddl_nothingsports_rate_v2$CREATE OR REPLACE FUNCTION public.nothingsports_rate_v2(target_user_id uuid, target_event_id text, target_phase text, target_rating integer, fixture_start timestamp with time zone, fixture_end timestamp with time zone, fixture_status text, fixture_sport text, fixture_gender text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare ts timestamptz:=clock_timestamp();expected text;award integer:=0;prior integer;reviewed_clock jsonb;begin
 -- bledisloe-host-timing-v1
 if nothingsports_recovery.fixture_alias_v1(target_event_id)='rugby-australia-new-zealand-2026-10-17' then
 fixture_start:='2026-10-17T05:00:00Z'::timestamptz;
 if fixture_status in('scheduled','upcoming') then fixture_end:='2026-10-17T08:00:00Z'::timestamptz;end if;
 end if;
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);
 if target_event_id='rugby-australia-south-africa-2026-09-27' then fixture_start:='2026-09-27T09:45:00Z'::timestamptz;end if;

 if target_rating not between 1 and 5 or target_phase not in('heat','pulse','impact') or target_user_id is null then raise exception 'invalid_rating';end if;
 if exists(select 1 from public.nothingsports_nsc_personas where user_id=target_user_id and moderation_flag) then raise exception 'profile_moderated';end if;
 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 perform pg_advisory_xact_lock(hashtextextended('fixture:'||target_event_id,0));
 reviewed_clock:=nothingsports_recovery.epl_reward_clock_v1(target_event_id,fixture_status,fixture_end);
 if reviewed_clock is not null then
  fixture_start:=(reviewed_clock->>'starts_at')::timestamptz;
  fixture_end:=(reviewed_clock->>'ends_at')::timestamptz;
  fixture_status:=reviewed_clock->>'status';fixture_sport:='football';
 end if;
 expected:=case when fixture_status in('cancelled','canceled','abandoned','postponed') then null when fixture_status in('completed','finished','final') then 'impact' when fixture_status in('live','inprogress','in_progress','in-progress') then 'pulse' when fixture_start is null or ts<fixture_start then 'heat' when ts<fixture_end then 'pulse' else 'impact' end;
 if expected is null or expected<>target_phase then raise exception 'phase_action_mismatch';end if;

 insert into public.nothingsports_score_fixtures values(target_event_id,fixture_sport,fixture_gender,fixture_start,fixture_end,fixture_status)
 on conflict(event_id) do update set sport=excluded.sport,gender=excluded.gender,starts_at=excluded.starts_at,ends_at=excluded.ends_at,status=excluded.status;
 select rating into prior from public.nothingsports_nsc_contributions where user_id=target_user_id and event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and phase=target_phase order by greatest(updated_at,submitted_at) desc nulls last,(event_id=target_event_id) desc,contribution_id limit 1;
 if prior=target_rating and not exists(select 1 from public.nothingsports_score_votes where user_id=target_user_id and event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and phase=target_phase) then
 return jsonb_build_object('eventId',target_event_id,'phase',target_phase,'rating',target_rating,'submitted',true,'pointsAwarded',0,'replayed',true);end if;
 if target_phase='heat' then
 if cardinality(nothingsports_recovery.epl_operating_ids_v1(target_event_id))>1 and exists(select 1 from public.nothingsports_predictions x where x.user_id=target_user_id and x.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and (x.resolved_at is not null or x.matched_user_id is not null or x.result not in('pending','unscored'))) then raise exception 'anticipation_already_settled';end if;
 insert into public.nothingsports_predictions(user_id,event_id,rating,created_at,updated_at,result) values(target_user_id,target_event_id,target_rating,ts,ts,case when fixture_start is null then 'unscored' else 'pending' end)
 on conflict(user_id,event_id) do update set rating=excluded.rating,updated_at=excluded.updated_at,result=excluded.result where nothingsports_predictions.result in('pending','unscored');end if;
 insert into public.nothingsports_score_votes values(target_user_id,target_event_id,target_phase,target_rating,ts) on conflict do nothing;
 insert into public.nothingsports_nsc_contributions(event_id,user_id,phase,bucket_start,rating,tags,submitted_at,updated_at,scoring_version,maximum_points)
 values(target_event_id,target_user_id,target_phase,'1970-01-01T00:00:00Z'::timestamptz,target_rating,'{}',ts,ts,'anticipation.v2',case when target_phase='heat' then 20 else 2 end) on conflict(event_id,user_id,phase,bucket_start) do update set rating=excluded.rating,updated_at=excluded.updated_at,scoring_version=excluded.scoring_version,maximum_points=excluded.maximum_points;
 award:=public.nothingsports_nsc_award_points(target_user_id,target_event_id,case when target_phase='pulse' then 'pulse_participation' else target_phase||'_rating' end,case when target_phase='heat' then 1 else 2 end,ts);
 if target_phase<>'heat' then perform public.nothingsports_resolve_predictions(target_event_id);end if;
 return jsonb_build_object('eventId',target_event_id,'phase',target_phase,'rating',target_rating,'submitted',true,'submittedAt',ts,'pointsAwarded',award,'basePointsAwarded',award,'foresightEligible',target_phase='heat' and fixture_start is not null);
end $function$;$ddl_nothingsports_rate_v2$;
 execute $ddl_nothingsports_resolve_predictions$CREATE OR REPLACE FUNCTION public.nothingsports_resolve_predictions(target_event_id text, confirmed_end timestamp with time zone DEFAULT NULL::timestamp with time zone, final_status text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.nothingsports_prediction_rules;p record;n integer;avg_rating numeric;answer integer;outcome text;total integer:=0;begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 perform pg_advisory_xact_lock(hashtextextended('fixture:'||target_event_id,0));
 select * into r from public.nothingsports_prediction_rules where event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) order by (event_id=target_event_id) desc limit 1;
 if r.version is distinct from 'consensus.v1' then return public.nothingsports_resolve_predictions_legacy(target_event_id,confirmed_end,final_status);end if;
 if final_status in('completed','finished','final','cancelled','canceled','abandoned') then
  update public.nothingsports_score_fixtures set status=final_status,ends_at=coalesce(r.completed_at,confirmed_end,clock_timestamp()) where event_id=target_event_id;
  select * into r from public.nothingsports_prediction_rules where event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) order by (event_id=target_event_id) desc limit 1;
 end if;
 if r.settled_at is not null then return 0;end if;
 if r.cutoff is null or clock_timestamp()<r.cutoff then return 0;end if;
 for p in select distinct on(x.user_id) x.*,f.starts_at,f.status from public.nothingsports_predictions x join public.nothingsports_score_fixtures f on f.event_id=target_event_id where x.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and x.result='pending'
 and not exists(select 1 from public.nothingsports_predictions done where done.user_id=x.user_id and done.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and (done.resolved_at is not null or done.matched_user_id is not null or done.result not in('pending','unscored')))
 order by x.user_id,x.updated_at desc,(x.event_id=target_event_id) desc,x.created_at desc loop
  select count(*),avg(v.rating) into n,avg_rating from (select distinct on(raw.user_id) raw.* from public.nothingsports_consensus_votes raw where raw.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and raw.user_id<>p.user_id and raw.recorded_at between r.completed_at and r.cutoff and not exists(select 1 from public.nothingsports_nsc_personas m where m.user_id=raw.user_id and m.moderation_flag) order by raw.user_id,raw.recorded_at desc,(raw.event_id=target_event_id) desc) v;
  answer:=round(avg_rating)::integer;
  outcome:=case when p.status in('cancelled','canceled','abandoned') then 'cancelled' when p.starts_at is null or p.updated_at>=p.starts_at or n=0 then 'unscored' when answer=p.rating then 'success' else 'miss' end;
  update public.nothingsports_predictions set result=outcome,resolved_at=clock_timestamp() where user_id=p.user_id and event_id=p.event_id and result='pending';
  insert into public.nothingsports_consensus_receipts values(p.event_id,p.user_id,r.version,r.cutoff,avg_rating,answer,n,outcome) on conflict do nothing;
  -- Existing points -> inbox trigger creates the successful reward receipt atomically.
  if outcome='success' then perform public.nothingsports_nsc_award_points(p.user_id,target_event_id,'foresight_bonus',19);total:=total+1;
  else insert into public.nothingsports_inbox(recipient_user_id,kind,source_key,event_id,title,detail)
   values(p.user_id,'system','consensus:'||target_event_id,target_event_id,'Anticipation rating settled','Open your rewards for the outcome. Participation points are retained.') on conflict(recipient_user_id,source_key) do nothing;
  end if;
 end loop;
 update public.nothingsports_prediction_rules set settled_at=clock_timestamp() where event_id=r.event_id;
 return total;
end $function$;$ddl_nothingsports_resolve_predictions$;
 execute $ddl_nothingsports_resolve_predictions_legacy$CREATE OR REPLACE FUNCTION public.nothingsports_resolve_predictions_legacy(target_event_id text, confirmed_end timestamp with time zone DEFAULT NULL::timestamp with time zone, final_status text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare p record;peer uuid;has_peer boolean;total integer:=0;deadline timestamptz;begin
 -- reviewed-fixture-rpc-identity-v1
 target_event_id:=nothingsports_recovery.fixture_alias_v1(target_event_id);

 perform pg_advisory_xact_lock(hashtextextended('nsc-awards-v2',0));
 perform pg_advisory_xact_lock(hashtextextended('fixture:'||target_event_id,0));
 if final_status in('completed','finished','final','cancelled','canceled','abandoned') and confirmed_end is not null then
 update public.nothingsports_score_fixtures set ends_at=confirmed_end,status=final_status where event_id=target_event_id;
 end if;
 select ends_at+interval '48 hours' into deadline from public.nothingsports_score_fixtures where event_id=target_event_id and status in('completed','finished','final','cancelled','canceled','abandoned');
 for p in select distinct on(x.user_id) x.*,f.starts_at,f.status from public.nothingsports_predictions x join public.nothingsports_score_fixtures f on f.event_id=target_event_id where x.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and x.result='pending'
 and not exists(select 1 from public.nothingsports_predictions done where done.user_id=x.user_id and done.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and (done.resolved_at is not null or done.matched_user_id is not null or done.result not in('pending','unscored')))
 order by x.user_id,x.updated_at desc,(x.event_id=target_event_id) desc,x.created_at desc loop
 if p.starts_at is null or p.updated_at>=p.starts_at then continue;end if;
 if p.status in('cancelled','canceled','abandoned') then
 update public.nothingsports_predictions set result='cancelled',resolved_at=clock_timestamp() where user_id=p.user_id and event_id=p.event_id and result='pending';continue;end if;
 select v.user_id into peer from (select distinct on(raw.user_id,raw.phase) raw.* from public.nothingsports_score_votes raw where raw.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and raw.phase in('pulse','impact') order by raw.user_id,raw.phase,raw.recorded_at desc,(raw.event_id=target_event_id) desc) v where v.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and v.user_id<>p.user_id and v.phase in('pulse','impact') and v.rating=p.rating and v.recorded_at>=p.starts_at and (deadline is null or v.recorded_at<=deadline)
 and not exists(select 1 from public.nothingsports_nsc_personas m where m.user_id=v.user_id and m.moderation_flag) order by v.recorded_at limit 1;
 if peer is not null then
 update public.nothingsports_predictions set result='success',matched_user_id=peer,resolved_at=clock_timestamp() where user_id=p.user_id and event_id=p.event_id and result='pending';
 perform public.nothingsports_nsc_award_points(p.user_id,target_event_id,'foresight_bonus',19);total:=total+1;
 elsif deadline is not null and clock_timestamp()>=deadline then
 select exists(select 1 from (select distinct on(raw.user_id,raw.phase) raw.* from public.nothingsports_score_votes raw where raw.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and raw.phase in('pulse','impact') order by raw.user_id,raw.phase,raw.recorded_at desc,(raw.event_id=target_event_id) desc) v where v.event_id=any(nothingsports_recovery.epl_operating_ids_v1(target_event_id)) and v.user_id<>p.user_id and v.phase in('pulse','impact') and v.recorded_at between p.starts_at and deadline and not exists(select 1 from public.nothingsports_nsc_personas m where m.user_id=v.user_id and m.moderation_flag)) into has_peer;
 update public.nothingsports_predictions set result=case when has_peer then 'miss' else 'unscored' end,resolved_at=clock_timestamp() where user_id=p.user_id and event_id=p.event_id and result='pending';
 end if;
 end loop;return total;
end $function$;$ddl_nothingsports_resolve_predictions_legacy$;
 execute $ddl_private_ready$create or replace function nothingsports_recovery.epl_identity_ready_v1()
returns boolean language sql stable security definer set search_path='' as $body$
 select exists(select 1 from nothingsports_recovery.coverage_repair_versions where version='epl-provider-identity.20261013' and completed_at is not null);
$body$;
revoke all on function nothingsports_recovery.epl_identity_ready_v1() from public,anon,authenticated;
grant execute on function nothingsports_recovery.epl_identity_ready_v1() to service_role;;$ddl_private_ready$;
 execute $ddl_public_ready$create or replace function public.nothingsports_epl_identity_ready()
returns boolean language sql stable set search_path='' as $body$select nothingsports_recovery.epl_identity_ready_v1();$body$;
revoke all on function public.nothingsports_epl_identity_ready() from public,anon,authenticated;
grant execute on function public.nothingsports_epl_identity_ready() to service_role;;$ddl_public_ready$;

 foreach t in array event_tables loop
  execute format('select md5(coalesce(string_agg(to_jsonb(r)::text,'''' order by to_jsonb(r)::text),'''')) from public.%I r where event_id=any($1)',t) into state_hash using ids;
  post_state:=post_state||jsonb_build_object(t,state_hash);
  if t not in('nothingsports_score_fixtures','nothingsports_prediction_rules') and state_hash is distinct from before_state->>t then raise exception 'EPL customer activity changed during preparation: %',t;end if;
 end loop;
 select jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('acl',p.proacl::text,'owner',p.proowner,'definer',p.prosecdef,'config',p.proconfig)) from pg_proc p where p.oid in(select key::regprocedure::oid from jsonb_each(expected_functions)) into security_after;
 if security_before is distinct from security_after then raise exception 'EPL existing function ownership/grants/security changed';end if;
 select jsonb_object_agg(p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))) into function_post from pg_proc p join pg_namespace ns on ns.oid=p.pronamespace where p.oid in(select key::regprocedure::oid from jsonb_each(expected_functions)) or ns.nspname='nothingsports_recovery' and p.proname in('epl_operating_ids_v1','epl_identity_ready_v1','epl_reward_clock_v1') or ns.nspname='public' and p.proname='nothingsports_epl_identity_ready';
 select jsonb_build_object(
 'reminderIntents',(select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by to_jsonb(r)::text),'')) from public.nothingsports_reminder_intents r where r.fixture_id=any(ids) or r.aliases ?| ids),
 'privateRooms',(select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by to_jsonb(r)::text),'')) from public.nothingsports_chat_rooms r where r.canonical_fixture_id=any(ids)),
 'savedState',(select md5(coalesce(string_agg(to_jsonb(r)::text,'' order by to_jsonb(r)::text),'')) from public.nothingsports_user_state r)) into aux_after;
 if aux_after is distinct from aux_before then raise exception 'EPL saved choices/private references changed during preparation';end if;
 select jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('acl',p.proacl::text,'owner',p.proowner,'definer',p.prosecdef,'config',p.proconfig)) from pg_proc p where p.oid in(select key::regprocedure::oid from jsonb_each(function_post)) into security_post;
 update nothingsports_recovery.coverage_repair_versions set inventory=jsonb_build_object('mode','forward-only/no-customer-preimages','beforeState',before_state,'postState',post_state,'securityBefore',security_before,'functionPostState',function_post,'functionSecurityPost',security_post,'auxPostState',aux_after,'triggerState',trigger_state,'addedParents',added_parents,'addedRules',added_rules,'scope',to_jsonb(ids)),completed_at=clock_timestamp() where version=version_id;
end $epl_apply$;
